from pathlib import Path
import pandas as pd,numpy as np
P=Path(__file__).resolve().parent;O=P.parent/'cover_exhaustive_2026_09';reg=pd.read_csv(O/'stock_coverage.csv').set_index('symbol');x=pd.read_parquet(P/'pilot_close_statistics.parquet');x=x[(x.stat_type==11)&(x.update_action==1)].copy();x['date']=x.ts_event.dt.tz_convert('America/New_York').dt.tz_localize(None).dt.normalize();rows=[];details=[]
for sym,z in x.groupby('symbol'):
 z=z.sort_values('ts_event').drop_duplicates('date',keep='last').set_index('date');d=pd.read_parquet(reg.loc[sym,'path']);d.index=pd.to_datetime(d.index.date);sp=d['Stock Splits'].replace(0,1);future=sp.iloc[::-1].cumprod().iloc[::-1]/sp;nom=d.Close*future;compare=pd.DataFrame({'official_close':z.price,'local_nominal_close':nom}).dropna();compare['relative_difference']=compare.official_close/compare.local_nominal_close-1;compare['symbol']=sym;details.append(compare.reset_index(names='date'));rows.append(dict(symbol=sym,compared_days=len(compare),over_1bp=int((compare.relative_difference.abs()>.0001).sum()),over_10bp=int((compare.relative_difference.abs()>.001).sum()),over_100bp=int((compare.relative_difference.abs()>.01).sum()),max_difference=compare.relative_difference.abs().max(),median_difference=compare.relative_difference.abs().median()))
pd.DataFrame(rows).to_csv(P/'pilot_price_audit.csv',index=False);pd.concat(details).to_parquet(P/'pilot_price_comparisons.parquet',index=False);print(pd.DataFrame(rows).to_string(index=False))
